const app = document.querySelector('#app');
const modal = document.querySelector('#modal');
const photo = (id, width = 1200) => `https://images.unsplash.com/${id}?auto=format&fit=crop&w=${width}&q=85`;
const homes = [
 {id:'as-101',title:'A little room to breathe',area:'Wanowrie',beds:2,rent:24000,size:1050,furnish:'Semi-furnished',image:'photo-1600607687920-4e2a09cf159d'},
 {id:'as-102',title:'Light-filled family living',area:'Fatima Nagar',beds:3,rent:32000,size:1420,furnish:'Furnished',image:'photo-1600210492486-724fe5c67fb0'},
 {id:'as-103',title:'Your quiet corner of Pune',area:'Wanwadi',beds:2,rent:22000,size:980,furnish:'Unfurnished',image:'photo-1600566753086-00f18fb6b3ea'},
 {id:'as-104',title:'Space for a fresh beginning',area:'Salunke Vihar',beds:3,rent:35000,size:1580,furnish:'Semi-furnished',image:'photo-1600607687939-ce8a6c25118c'},
 {id:'as-105',title:'An easy place to settle in',area:'Fatima Nagar',beds:1,rent:16500,size:640,furnish:'Furnished',image:'photo-1600210491892-03d54c0aaf87'},
 {id:'as-106',title:'Home, with a view',area:'Wanwadi',beds:2,rent:27000,size:1120,furnish:'Furnished',image:'photo-1600047509807-ba8f99d2cdde'}
];
function read(key, fallback) {try {return JSON.parse(localStorage.getItem(key)) ?? fallback;} catch {return fallback;}}
let saved = read('as-saved', []);
let checks = read('as-checks', []);
let drafts = read('as-drafts', []);
const tasks = [['Find your home','Shortlist a home and arrange a viewing.'],['Get the paperwork ready','Review your agreement and handover arrangements.'],['Make moving day easier','Organise movers, cleaning and utilities.'],['Settle into your neighbourhood','Collect your keys and check your home together.']];
const escapeHtml = value => String(value).replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const money = amount => '₹' + amount.toLocaleString('en-IN');
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Your browser could not save this change.');}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';setTimeout(()=>el.style.display='none',3500);}
function header(){return `<header><a class="brand" href="#home"><span class="mark">⌂</span>AanganSetu</a><nav><a href="#homes">Find a home</a><a href="#services">Move-in services</a><a href="#move">My move</a><a href="#saved">Saved (${saved.length})</a><a class="button" href="#owner">List your home ↗</a></nav><button class="mobile-menu" aria-label="Open navigation" onclick="document.querySelector('nav').classList.toggle('open')">☰</button></header>`;}
function footer(){return `<footer><a class="brand" href="#home"><span class="mark">⌂</span>AanganSetu</a><p>Rooted in Wanwadi. Built around your next chapter.<br>Independent housing portal · Free during launch</p><a href="#account">My account ↗</a></footer>`;}
function card(home){return `<article class="property"><div class="property-image"><a href="#property/${home.id}"><img src="${photo(home.image)}" alt="Illustrative interior for ${home.title}" loading="lazy"></a><button class="save" aria-label="${saved.includes(home.id)?'Unsave':'Save'} ${home.title}" onclick="toggleSave('${home.id}')">${saved.includes(home.id)?'♥':'♡'}</button><span class="image-label">Sample home</span></div><div class="property-title"><a href="#property/${home.id}"><h3>${home.title}</h3></a><strong>${money(home.rent)}<span class="muted"> / mo</span></strong></div><div class="meta">${home.area}, Pune · ${home.beds} bedrooms · ${home.size} sq ft</div><div class="card-bottom"><span>${home.furnish}</span><button class="text-button" onclick="shareHome('${home.id}')">Share photos ↗</button></div></article>`;}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist('as-saved',saved);render();}
function services(){return `<div class="services">${[['⌂','Home viewings','Get a closer look before you make the journey. Request a local viewing.'],['▦','Packers & movers','Plan your move, from the first box to the final delivery.'],['✧','A fresh start','Arrange cleaning and small fixes before you collect your keys.'],['⌁','Everyday essentials','Get help organising internet, utilities and your first days at home.']].map(([icon,title,text])=>`<article><div class="service-icon">${icon}</div><h3>${title}</h3><p>${text}</p><button class="text-button" onclick="requestService('${title}')">Request help ↗</button></article>`).join('')}</div>`;}
function steps(){return `<div class="steps">${tasks.map((task,i)=>`<label class="step"><input type="checkbox" ${checks.includes(i)?'checked':''} onchange="setCheck(${i},this.checked)"><span>${task[0]}<small>${task[1]}</small></span></label>`).join('')}</div>`;}
function setCheck(index,value){checks=value?[...new Set([...checks,index])]:checks.filter(x=>x!==index);persist('as-checks',checks);if(location.hash==='#move')render();}
function homePage(){return `<div class="hero">${header()}<div class="hero-content"><div><div class="eyebrow">A new beginning, closer to home</div><h1>A place to call<br>your own.</h1></div><div class="hero-aside">Thoughtful homes. A smoother move.<br>For those who serve, and the families<br>who make every posting a home.<br><a href="#homes" class="button light">Find your home <span>↗</span></a></div></div><div class="hero-foot"><span>Wanwadi & neighbouring communities, Pune</span><span>Free to explore. Clear from the start.</span></div></div><form class="search" id="search"><div class="field"><label for="location">Where would you like to live?</label><select id="location"><option value="">All neighbourhoods</option>${['Wanwadi','Wanowrie','Fatima Nagar','Salunke Vihar'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="bedrooms">Your space</label><select id="bedrooms"><option value="">Any bedrooms</option><option value="1">1 bedroom</option><option value="2">2 bedrooms</option><option value="3">3 bedrooms</option></select></div><div class="field"><label for="budget">Monthly budget</label><select id="budget"><option value="">Any budget</option value="20000">Up to ₹20,000</option><option value="25000">Up to ₹25,000</option><option value="35000">Up to ₹35,000</option></select></div><button class="button">Explore homes ↗</button></form><section class="section intro"><div class="eyebrow">A sense of belonging</div><div><h2>You serve the community.<br>Let us help you find yours.</h2><p>AanganSetu brings homes and moving essentials together, starting in Wanwadi. A simpler way for service families to find their space, plan the details, and feel at home.</p><div class="audience">${['Armed forces','CRPF & CAPF','Government employees','Doctors','Veterans & Army brats'].map(x=>`<span class="pill">${x}</span>`).join('')}</div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Room for your next chapter</div><h2>Find your kind of home.</h2></div><a class="button outline" href="#homes">View all homes ↗</a></div><div class="cards">${homes.slice(0,3).map(card).join('')}</div><p class="muted">Explore sample listings with illustrative photography. Real inventory is coming soon.</p></section><section class="section"><div class="section-head"><div><div class="eyebrow">More than finding a home</div><h2>From moving to settling in.</h2></div><a href="#services">Explore services ↗</a></div>${services()}</section><section class="section journey"><div><div class="eyebrow">One step at a time</div><h2>A fresh start.<br>A little less to organise.</h2><p>Your move-in checklist keeps the little things together, so you can focus on the people coming with you.</p><a class="button" href="#move">Plan my move ↗</a></div>${steps()}</section><section class="section"><div class="section-head"><div><div class="eyebrow">Start somewhere familiar</div><h2>Explore the neighbourhood.</h2></div><span class="muted">Pune, Maharashtra</span></div><div class="neighbourhoods">${['Wanwadi','Fatima Nagar','Salunke Vihar'].map((area,i)=>`<a class="neighbourhood" href="#homes?area=${encodeURIComponent(area)}"><span class="muted">${['Our starting point','Everyday convenience','Room to settle'][i]}</span><h3>${area} ↗</h3><p>Explore homes in the neighbourhood.</p></a>`).join('')}</div></section><div class="cta"><div><h2>Your home could be<br>someone’s next beginning.</h2><p>List your property. Welcome a new chapter.</p></div><a class="button lime" href="#owner">List your home for free ↗</a></div>${footer()}`;}
function browse(savedOnly=false){const query=new URLSearchParams(location.hash.split('?')[1]||'');const area=query.get('area')||'';const beds=query.get('beds')||'';const budget=query.get('budget')||'';let filtered=homes.filter(h=>(!savedOnly||saved.includes(h.id))&&(!area||h.area===area)&&(!beds||h.beds===Number(beds))&&(!budget||h.rent<=Number(budget)));return `${header()}<div class="page-title"><div class="eyebrow">Your next chapter, in Pune</div><h1 style="font-size:52px">${savedOnly?'Homes you love.':'Find a place that feels right.'}</h1><form id="filter" class="filters"><select name="area" aria-label="Neighbourhood"><option value="">All neighbourhoods</option>${['Wanwadi','Wanowrie','Fatima Nagar','Salunke Vihar'].map(x=>`<option ${x===area?'selected':''}>${x}</option>`).join('')}</select><select name="beds" aria-label="Bedrooms"><option value="">Any bedrooms</option>${[1,2,3].map(x=>`<option value="${x}" ${String(x)===beds?'selected':''}>${x} bedrooms</option>`).join('')}</select><select name="budget" aria-label="Budget"><option value="">Any budget</option>${[20000,25000,35000].map(x=>`<option value="${x}" ${String(x)===budget?'selected':''}>Up to ${money(x)}</option>`).join('')}</select><button class="button">Apply filters</button><a class="button outline" href="#${savedOnly?'saved':'homes'}">Reset</a></form><p>${filtered.length} sample homes · Illustrative photography</p></div><section class="section"><div class="cards">${filtered.map(card).join('')||'<div class="empty">No homes here yet. Try another filter or save a home you like.</div>'}</div></section>${footer()}`;}
function showModal(content){document.querySelector('#modal-body').innerHTML=content;modal.showModal();}
function shareHome(id){const url=new URL(location.href);url.hash='photos/'+id;showModal(`<div class="eyebrow">Share a first impression</div><h2>Just the photographs.</h2><p>This preview displays illustrative photos only. Anyone who can access this site can open the preview.</p><input aria-label="Share link" style="width:100%;padding:12px" readonly value="${escapeHtml(url.href)}"><div class="actions"><button class="button" id="copy">Copy link ↗</button><a class="button outline" href="${escapeHtml(url.href)}" target="_blank" rel="noopener">Open preview</a></div><p class="muted">The launch preview contains sample properties. Access controls for real listings will be connected with Supabase.</p>`);document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);toast('Photo link copied');}catch{toast('Select and copy the link above.');}};}
function requestService(service){showModal(`<h2>${escapeHtml(service)}</h2><p>Save your request locally while the service network is being prepared.</p><form class="form" id="request"><label>Your name<input name="name" required maxlength="100" autocomplete="name"></label><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Preferred date<input name="date" type="date" required min="${new Date().toLocaleDateString('en-CA')}"></label><label>What would help?<textarea name="notes" maxlength="2000"></textarea></label><button class="button">Save request draft</button><span class="muted">Stored on this browser. A provider receives your request after the live service is connected.</span></form>`);document.querySelector('#request').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const requests=read('as-requests',[]);requests.push({...data,service});persist('as-requests',requests);modal.close();toast('Request draft saved. Find it in My account.');};}
function propertyPage(id){const h=homes.find(x=>x.id===id);if(!h)return `${header()}<section class="section"><h2>Home unavailable</h2><a href="#homes">Browse homes ↗</a></section>`;return `${header()}<section class="section"><div class="eyebrow">Sample home · ${h.area}, Pune</div><div class="section-head"><h2>${h.title}</h2><strong>${money(h.rent)} / month</strong></div><img class="modal-photo" style="max-height:600px" src="${photo(h.image,2000)}" alt="Illustrative property interior"><div class="dashboard"><div><h3>${h.beds} bedrooms · ${h.size} sq ft</h3><p>${h.furnish}</p><p class="muted">Sample listing ${h.id.toUpperCase()}<br>Photos are illustrative. Availability and owner checks are pending.</p></div><div><h2>A space for your next chapter.</h2><p>Explore this sample home and try the viewing request and move-in checklist. Real property details and owner-approved photographs will be added at launch.</p><div class="notice">Rent is an illustrative monthly amount. Deposit, maintenance and any service charges will be stated on real listings before an enquiry proceeds.</div><div class="actions"><button class="button" onclick="requestService('Viewing for ${h.id}')">Request a viewing ↗</button><button class="button outline" onclick="shareHome('${h.id}')">Share photos</button><button class="button outline" onclick="toggleSave('${h.id}')">${saved.includes(h.id)?'Saved ♥':'Save home ♡'}</button></div></div></div></section>${footer()}`;}
function ownerPage(){return `${header()}<section class="section"><div class="eyebrow">Welcome a new beginning</div><h2>List your home.</h2><div class="dashboard"><div><p>Create a property draft for the launch. Your draft stays on this browser until your account and Supabase are connected.</p><div class="notice">Free at launch. Owner contact details and exact addresses belong in the protected listing workflow.</div><h3>Your drafts</h3>${drafts.map((d,i)=>`<div class="listing-row"><span>${escapeHtml(d.title)}<br><small>${escapeHtml(d.area)} · ${money(Number(d.rent))}</small></span><button onclick="deleteDraft(${i})" class="text-button">Delete</button></div>`).join('')||'<p class="muted">Your first listing starts here.</p>'}</div><form class="form panel" id="listing"><label>Property title<input name="title" required maxlength="100" placeholder="A bright family home in Wanwadi"></label><label>Neighbourhood<select name="area">${['Wanwadi','Wanowrie','Fatima Nagar','Salunke Vihar'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Monthly rent in rupees<input name="rent" type="number" min="1" max="1000000" required></label><label>Bedrooms<select name="beds"><option>1</option><option>2</option><option>3</option><option>4</option></select></label><label>Furnishing<select name="furnishing"><option>Unfurnished</option><option>Semi-furnished</option><option>Furnished</option></select></label><label>Notes<textarea name="notes" maxlength="2000"></textarea></label><p class="muted">Photo uploads will be available with your connected storage.</p><button class="button">Save listing draft ↗</button></form></div></section>${footer()}`;}
function deleteDraft(i){drafts.splice(i,1);persist('as-drafts',drafts);render();}
function account(){const requests=read('as-requests',[]);return `${header()}<section class="section"><div class="eyebrow">Everything in one place</div><h2>Your space.</h2><div class="notice">Preview mode · Saved homes, requests and progress are stored on this device. Account sign-in becomes available after Supabase is connected.</div><div class="actions"><a href="#saved" class="button">${saved.length} saved homes ↗</a><a href="#move" class="button outline">My move ↗</a><a href="#owner" class="button outline">My listings ↗</a></div><h3 style="margin-top:40px">Request drafts</h3>${requests.map(r=>`<div class="listing-row"><strong>${escapeHtml(r.service)}</strong><span>${escapeHtml(r.date)} · Draft, awaiting live connection</span></div>`).join('')||'<p>No request drafts yet.</p>'}</section>${footer()}`;}
function render(){const route=location.hash.slice(1).split('?')[0]||'home';if(modal.open)modal.close();if(route.startsWith('photos/')){const h=homes.find(x=>x.id===route.split('/')[1]);app.innerHTML=h?`<div class="share-gallery"><img src="${photo(h.image,2000)}" alt="Illustrative property photograph"><div class="share-back">Sample photography · AanganSetu</div></div>`:'<div class="empty">Photo preview unavailable.</div>';return;}let content;if(route==='home')content=homePage();else if(route==='homes'||route==='saved')content=browse(route==='saved');else if(route.startsWith('property/'))content=propertyPage(route.split('/')[1]);else if(route==='services')content=`${header()}<section class="section"><div class="eyebrow">Make yourself at home</div><h2>A smoother move starts here.</h2><p>Plan the help you need. Service requests are saved as drafts during the preview.</p>${services()}</section>${footer()}`;else if(route==='move')content=`${header()}<section class="section journey"><div><div class="eyebrow">Your move, organised</div><h2>A little closer to home.</h2><p>${checks.length} of ${tasks.length} steps complete</p><div class="progress"><span style="width:${checks.length/tasks.length*100}%"></span></div><a class="button" href="#services">Find help with your move ↗</a></div>${steps()}</section>${footer()}`;else if(route==='owner')content=ownerPage();else if(route==='account')content=account();else content=`${header()}<section class="section"><h2>Page unavailable</h2><a href="#home">Return home ↗</a></section>`;app.innerHTML=content;const search=document.querySelector('#search');if(search)search.onsubmit=e=>{e.preventDefault();location.hash='homes?'+new URLSearchParams({area:document.querySelector('#location').value,beds:document.querySelector('#bedrooms').value,budget:document.querySelector('#budget').value});};const filter=document.querySelector('#filter');if(filter)filter.onsubmit=e=>{e.preventDefault();location.hash=route+'?'+new URLSearchParams(new FormData(filter));};const listing=document.querySelector('#listing');if(listing)listing.onsubmit=e=>{e.preventDefault();drafts.push(Object.fromEntries(new FormData(listing)));persist('as-drafts',drafts);render();toast('Listing draft saved on this device.');};}
document.querySelector('.close').onclick=()=>modal.close();
modal.addEventListener('click',event=>{if(event.target===modal)modal.close();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
render();

